function element(tag,attrs={},text){const el=document.createElement(tag);for(const [k,v]of Object.entries(attrs)){if(k==='class')el.className=v;else el.setAttribute(k,v);}if(text!==undefined)el.textContent=text;return el;}
function button(text,action,className=''){const b=element('button',{type:'button',class:className},text);b.addEventListener('click',action);return b;}
export function validateLogoDocument(data){
 if(!data||data.type!=='webcad-logo'||data.version!==1||data.units!=='mm')throw new Error('LOGO 文件须为 webcad-logo v1，单位 mm。');
 const dimensions=Array.isArray(data.sizeMm)?data.sizeMm:[data.sizeMm?.width,data.sizeMm?.height];
 if(typeof data.name!=='string'||!data.name.trim()||!data.source||!['string','object'].includes(typeof data.source)||dimensions.length!==2||dimensions.some(n=>typeof n!=='number'||!Number.isFinite(n)||n<=0))throw new Error('LOGO 缺少名称、来源或有效尺寸。');
 if(!Array.isArray(data.regions)||!data.regions.length)throw new Error('LOGO 必须包含有效的闭合轮廓。');
 const ring=points=>{if(!Array.isArray(points)||points.length<3||points.some(p=>!Array.isArray(p)||p.length!==2||p.some(n=>typeof n!=='number'||!Number.isFinite(n))))throw new Error('LOGO 坐标必须是有限的二维数值，且闭合轮廓面积不能为零。');let area=0;for(let i=0;i<points.length;i++){const a=points[i],b=points[(i+1)%points.length];area+=a[0]*b[1]-b[0]*a[1];}if(!Number.isFinite(area)||Math.abs(area)<1e-12)throw new Error('LOGO 坐标必须是有限的二维数值，且闭合轮廓面积不能为零。');return points.map(p=>[p[0],p[1]]);};
 const regions=data.regions.map(region=>{if(!region||!Array.isArray(region.holes??[]))throw new Error('LOGO 必须包含有效的闭合轮廓。');return {outer:ring(region.outer),holes:(region.holes||[]).map(ring)};});
 return {name:data.name.trim(),source:data.source,sizeMm:data.sizeMm,regions};
}
function logoSummary(logo,profile=false){
 const box=element('div',{class:'logo-summary'}),info=element('dl',{class:'logo-facts'});let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity,loops=0;
 for(const region of logo.regions||[])for(const ring of [region.outer,...(region.holes||[])]){loops++;for(const [x,y]of ring){minX=Math.min(minX,x);minY=Math.min(minY,y);maxX=Math.max(maxX,x);maxY=Math.max(maxY,y);}}
 const width=maxX-minX,height=maxY-minY,declared=Array.isArray(logo.sizeMm)?logo.sizeMm:[logo.sizeMm?.width,logo.sizeMm?.height];
 for(const [label,value]of [['名称',logo.name||(profile?'路径轮廓':'LOGO')],['轮廓尺寸',`${width.toFixed(3)} × ${height.toFixed(3)} mm`],['文件标注尺寸',declared.every(Number.isFinite)?`${declared[0]} × ${declared[1]} mm`:'—'],['填充区域',String(logo.regions?.length||0)],['闭合轮廓数',String(loops)],['来源',typeof logo.source==='string'?logo.source:JSON.stringify(logo.source||{})]]){info.append(element('dt',{},label),element('dd',{'data-no-translate':''},value));}
 box.append(info);if(Number.isFinite(width)&&Number.isFinite(height)&&width>0&&height>0){const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg'),pad=Math.max(width,height)*.07;svg.setAttribute('class','logo-contour-preview');svg.setAttribute('viewBox',`${minX-pad} ${-maxY-pad} ${width+2*pad} ${height+2*pad}`);svg.setAttribute('role','img');svg.setAttribute('aria-label',profile?'路径轮廓':'LOGO');const fill=logo.source?.displayColor||logo.source?.original?.displayColor||logo.source?.fillColor||logo.source?.original?.fillColor||'#177c79';for(const region of logo.regions){const path=document.createElementNS(ns,'path');path.setAttribute('fill-rule','evenodd');path.setAttribute('d',[region.outer,...(region.holes||[])].map(points=>points.map(([x,y],i)=>`${i?'L':'M'}${x} ${-y}`).join(' ')+' Z').join(' '));path.style.fill=fill;path.setAttribute('stroke','#173b49');path.setAttribute('stroke-width',String(Math.max(width,height)*.003));svg.append(path);}box.append(svg,element('p',{class:'property-footnote'},profile?'填充显示轮廓区域；深色边线标识闭合路径。':'填充显示 SVG 原色；深色边线标识字形外框。'));}return box;
}
function logoPlacementControls(form,getLogo,element,button){
 const wrap=element('div',{class:'logo-placement-controls wide'}),anchor=element('select',{'aria-label':'LOGO 锚点'}),step=element('input',{type:'number',min:'0.001',step:'any',value:'0.1','aria-label':'微调步长 mm'});
 for(const [value,label] of [['center','中心'],['top-left','左上'],['top','上中'],['top-right','右上'],['left','左中'],['right','右中'],['bottom-left','左下'],['bottom','下中'],['bottom-right','右下']])anchor.append(element('option',{value},label));
 const offset=(axis,delta)=>{const field=form.elements.namedItem(axis);field.value=String(Number(field.value||0)+delta);field.dispatchEvent(new Event('input',{bubbles:true}));};
 let previous=[0,0];anchor.addEventListener('change',()=>{const logo=getLogo();if(!logo)return;const points=logo.regions.flatMap(r=>r.outer),xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);const [vertical,horizontal]=anchor.value==='center'?['middle','center']:anchor.value.includes('-')?anchor.value.split('-'):['middle',anchor.value];const x=horizontal==='left'?minX:horizontal==='right'?maxX:(minX+maxX)/2,y=vertical==='top'?maxY:vertical==='bottom'?minY:(minY+maxY)/2,scale=Number(form.elements.namedItem('scale')?.value||1),angle=Number(form.elements.namedItem('angle')?.value||0)*Math.PI/180,mx=form.elements.namedItem('mirrorX')?.checked?-1:1;const next=[-scale*(mx*x*Math.cos(angle)-y*Math.sin(angle)),-scale*(mx*x*Math.sin(angle)+y*Math.cos(angle))];offset('offsetX',next[0]-previous[0]);offset('offsetY',next[1]-previous[1]);previous=next;});
 const anchorLabel=element('label',{},'位置锚点 '),stepLabel=element('label',{},'微调步长 mm ');anchorLabel.append(anchor);stepLabel.append(step);wrap.append(anchorLabel,stepLabel);const nudge=(label,axis,sign)=>wrap.append(button(label,()=>{const amount=Number(step.value);if(!Number.isFinite(amount)||amount<=0)return;offset(axis,sign*amount);},'secondary'));nudge('←','offsetX',-1);nudge('→','offsetX',1);nudge('↓','offsetY',-1);nudge('↑','offsetY',1);wrap.append(element('p',{class:'property-footnote'},'锚点设定局部 X/Y 偏移；箭头按步长微调。预览后应用，历史步骤可继续修改偏移。'));return wrap;
}
